function askFindMtlSource(key){
  return { name:'FindMTL', url: ASK_FINDMTL[key] || ASK_FINDMTL.home,
           type:'Community directory', authoritative:false, timeSensitive:true, lastUpdated:'' };
}


/* ---------- Shared conversational templates ----------
   One place for the wording that is not an answer: greetings, thanks, farewell,
   the two failure cases, and the frame used when an answer came from outside
   CJHQ. Exported through ask-core.mjs so the WhatsApp bridge uses these rather
   than inventing its own strings, which is how mixed-language output starts.

   The two failure templates are deliberately different and must not be merged:
     noAnswer  - the system worked and found nothing verified
     busy      - the AI or search service failed
   Telling someone "there is no answer" because a provider returned 429 is a
   lie, and it is the lie a user would act on. Nothing about the provider,
   the quota, the status code or the stack ever reaches the person; that
   belongs in the log.                                                        */
