/* ---------- Session policy ----------
   The core is stateless and stays that way: it holds no chat ids, no history
   and no timers. What lives here is the DECISION - given a session record and
   the current time, is this active, expired, or a first-ever contact - so the
   rule is written and tested once instead of being re-derived in the bridge.

   The bridge owns everything stateful: the chat id, the stored record, when it
   is written, and when it is discarded. It calls askSessionState() and does
   what it says.

   Expiry is silent by design. Nothing here produces a message on expiry, and
   there is deliberately no template for one: a person who walked away five
   minutes ago should not get a notification telling them so. There is also no
   "anything else?" prompt - if they have another question they will send it. */
const ASK_SESSION_POLICY = {
  inactivityMs: 5 * 60 * 1000,   // 5 minutes, the whole of the rule
  contextTurns: 6,               // matches the window askAnswer already trims to
  notifyOnExpiry: false          // never. Left explicit so it cannot drift.
};

/* session: { sessionStartedAt, lastActivityAt, context[], everContacted }
   Anything missing is treated as absent rather than assumed, so a malformed or
   partial record degrades to "new session", never to a stale one.

   Returns:
     status        'new' | 'active' | 'expired'
     context       what to pass to askAnswer - ALWAYS empty unless active, so an
                   expired session cannot leak its previous turns into the next
                   message even if the bridge forgets to clear its own copy
     sendOnboarding  true only for a first-ever contact, not for a new session
     clearContext  the bridge should discard what it stored
     nextLastActivityAt  what to write back after handling the message      */
function askSessionState(session, now){
  const t = (typeof now === 'number') ? now : Date.now();
  const s = session || {};
  const last = Number(s.lastActivityAt);
  const everContacted = s.everContacted === true;
  const hasSession = Number.isFinite(last) && last > 0;
  const idle = hasSession ? (t - last) : Infinity;
  // >=, not >: exactly five minutes is expired. A boundary that favours
  // keeping context is the wrong way round for a privacy timeout.
  const expired = !hasSession || idle >= ASK_SESSION_POLICY.inactivityMs;

  const status = !hasSession ? 'new' : (expired ? 'expired' : 'active');
  const context = (status === 'active' && Array.isArray(s.context))
    ? s.context.slice(-ASK_SESSION_POLICY.contextTurns)
    : [];

  return {
    status,
    context,
    // A returning user whose session expired is a NEW SESSION, not a new user.
    // Onboarding is sent once, ever.
    sendOnboarding: !everContacted,
    clearContext: status !== 'active',
    idleMs: hasSession ? idle : null,
    nextLastActivityAt: t,
    nextSessionStartedAt: (status === 'active' && Number(s.sessionStartedAt)) || t
  };
}

/* An explicit goodbye may close the session immediately. It is optional
   handling - not a requirement, and it sends no closure notice. */
function askSessionShouldClose(message){
  return askSmallTalk(message) === 'goodbye';
}

/* Small-talk classifier, so the bridge does not run a greeting through the
   whole retrieval chain. Returns a template key or null. */
function askSmallTalk(q){
  const s = String(q || '').trim().toLowerCase();
  if(!s) return 'clarify';
  if(s.length > 40) return null;
  if(/^(hi|hello|hey|good (morning|afternoon|evening)|bonjour|salut|\u05e9\u05dc\u05d5\u05dd|\u05d4\u05d9\u05d9)[\s!.,]*$/i.test(s)) return 'greeting';
  if(/^(thanks|thank you|thx|ty|merci|\u05ea\u05d5\u05d3\u05d4|\u05a0?\u05ea\u05d5\u05d3\u05d4 \u05e8\u05d1\u05d4)[\s!.,]*$/i.test(s)) return 'thanks';
  if(/^(bye|goodbye|good ?night|see you|au revoir|bonne nuit|\u05dc\u05d4\u05ea\u05e8\u05d0\u05d5\u05ea|\u05d1\u05d9\u05d9)[\s!.,]*$/i.test(s)) return 'goodbye';
  return null;
}

function askEruv(q){
  // English, French (erouv/érouv) and Hebrew script.
  if(!/eruv|eiruv|erouv|\u05e2\u05d9\u05e8\u05d5\u05d1|\u05e2\u05d9\u05e8\u05d5\u05d5/i.test(q)) return null;
  const r = askAnswerShape();
  const L = askDetectLanguage(q); r.lang = L;
  r.handled = true; r.handler = 'Eruv'; r.timeSensitive = true;
  r.answer = askT({
    en:'Eruv status changes week to week, so I will not state whether it is up. Check the official Montreal Eruv page, which is updated by the people who inspect it.',
    fr:'Le statut de l\u2019\u00e9rouv change d\u2019une semaine \u00e0 l\u2019autre. Je n\u2019affirmerai donc pas s\u2019il est en fonction. Consultez la page officielle de l\u2019\u00c9rouv de Montr\u00e9al, mise \u00e0 jour par ceux qui l\u2019inspectent.',
    he:'\u05de\u05e6\u05d1 \u05d4\u05e2\u05d9\u05e8\u05d5\u05d1 \u05de\u05e9\u05ea\u05e0\u05d4 \u05de\u05e9\u05d1\u05d5\u05e2 \u05dc\u05e9\u05d1\u05d5\u05e2, \u05dc\u05db\u05df \u05dc\u05d0 \u05d0\u05e6\u05d9\u05d9\u05df \u05d0\u05dd \u05d4\u05d5\u05d0 \u05ea\u05e7\u05d9\u05df. \u05d9\u05e9 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d1\u05d0\u05ea\u05e8 \u05d4\u05e8\u05e9\u05de\u05d9 \u05e9\u05dc \u05e2\u05d9\u05e8\u05d5\u05d1 \u05de\u05d5\u05e0\u05d8\u05e8\u05d9\u05d0\u05dc.',
    yi:'\u05d3\u05e2\u05e8 \u05de\u05e6\u05d1 \u05e4\u05d5\u05e0\u05e2\u05dd \u05e2\u05d9\u05e8\u05d5\u05d1 \u05e2\u05e0\u05d3\u05e2\u05e8\u05d8 \u05d6\u05d9\u05da \u05d9\u05e2\u05d3\u05e2 \u05d5\u05d5\u05d0\u05da, \u05d3\u05e2\u05e8\u05d9\u05d1\u05e2\u05e8 \u05d6\u05d0\u05d2 \u05d0\u05d9\u05da \u05e0\u05d9\u05e9\u05d8 \u05e6\u05d9 \u05e2\u05e8 \u05d0\u05d9\u05d6 \u05d2\u05d5\u05d8 \u05d0\u05d3\u05e2\u05e8 \u05e0\u05d9\u05e9\u05d8. \u05e7\u05d5\u05e7\u05d8 \u05e0\u05d0\u05da \u05d0\u05d5\u05d9\u05e3 \u05d3\u05e2\u05e8 \u05d0\u05e4\u05d9\u05e6\u05d9\u05e2\u05dc\u05e2\u05e8 \u05de\u05d0\u05e0\u05d8\u05e8\u05e2\u05d0\u05dc \u05e2\u05d9\u05e8\u05d5\u05d1 \u05d1\u05dc\u05d0\u05d8 \u2014 \u05d6\u05d9\u05d9 \u05e4\u05e8\u05d9\u05e9\u05df \u05e2\u05e1 \u05d0\u05d5\u05d9\u05e3.'
  }, L);
  // Actions come from the structured record, so changing the official URL is a
  // one-line edit rather than a hunt through the handlers.
  const E = ASK_ERUV_RECORD;
  r.actions = [
    { label: askT({en:'Check Eruv Status', fr:'V\u00e9rifier le statut de l\u2019\u00e9rouv', he:'\u05d1\u05d3\u05d9\u05e7\u05ea \u05de\u05e6\u05d1 \u05d4\u05e2\u05d9\u05e8\u05d5\u05d1', yi:'\u05d6\u05e2\u05d8 \u05d3\u05e2\u05dd \u05e2\u05d9\u05e8\u05d5\u05d1 \u05de\u05e6\u05d1'}, L), url:E.statusPage, kind:'link' },
    { label: askT({en:'View Eruv Map', fr:'Voir la carte de l\u2019\u00e9rouv', he:'\u05de\u05e4\u05ea \u05d4\u05e2\u05d9\u05e8\u05d5\u05d1', yi:'\u05d6\u05e2\u05d8 \u05d3\u05d9 \u05e2\u05d9\u05e8\u05d5\u05d1 \u05de\u05d0\u05e4\u05e2'}, L), url:E.mapUrl, kind:'map' },
    { label: askT({en:'Eruv Website', fr:'Site de l\u2019\u00e9rouv', he:'\u05d0\u05ea\u05e8 \u05d4\u05e2\u05d9\u05e8\u05d5\u05d1', yi:'\u05e2\u05d9\u05e8\u05d5\u05d1 \u05d5\u05d5\u05e2\u05d1\u05d6\u05d9\u05d9\u05d8\u05dc'}, L), url:E.website, kind:'link' }
  ];
  r.sources = askSortSources([{ name:E.organization, url:E.website, type:'Eruv',
                                authoritative:true, timeSensitive:true, lastVerified:E.lastVerified }]);
  return r;
}

function askEmergency(q, opts){
  // "What is the emergency number for Chaverim?" is a question about a named
  // partner, not a medical emergency. Without this, the word "emergency" alone
  // routed it here and the person got the Hatzolah answer for a roadside
  // organization. Hatzolah itself still lands here, and so does any general
  // emergency question, because that is where the 911-first wording belongs.
  const namedOther = askOrgMatch(q, opts && opts.orgContacts)
    .filter(o => !/hatzol/i.test(o.name));
  if(namedOther.length && !/hatzol|\u05d4\u05e6\u05dc\u05d4/i.test(String(q || ''))) return null;
  if(!/hatzol|hatzalah|ambulance|emergency|paramedic|urgence|ambulancier|noytfal|\u05d4\u05e6\u05dc\u05d4|\u05e0\u05d5\u05d9\u05d8\u05e4\u05d0\u05dc|\u05d0\u05de\u05d1\u05d5\u05dc\u05d0\u05e0\u05e1/i.test(q)) return null;
  const r = askAnswerShape();
  const L = askDetectLanguage(q); r.lang = L;
  r.handled = true; r.handler = 'Emergency';
  r.answer = askT({
    en:'If this is a life-threatening emergency, call 911 first.\n\nHatzolah Montreal is the community volunteer emergency medical service. I will not quote a phone number from memory. Use the official site so you get the current one.',
    fr:'S\u2019il s\u2019agit d\u2019une urgence vitale, composez d\u2019abord le 911.\n\nHatzolah Montr\u00e9al est le service m\u00e9dical d\u2019urgence b\u00e9n\u00e9vole de la communaut\u00e9. Je ne citerai pas un num\u00e9ro de m\u00e9moire. Consultez le site officiel pour le num\u00e9ro \u00e0 jour.',
    he:'\u05d1\u05de\u05e7\u05e8\u05d4 \u05e9\u05dc \u05e1\u05db\u05e0\u05ea \u05d7\u05d9\u05d9\u05dd \u05d9\u05e9 \u05dc\u05d4\u05ea\u05e7\u05e9\u05e8 \u05ea\u05d7\u05d9\u05dc\u05d4 \u05dc-911.\n\n\u05d4\u05e6\u05dc\u05d4 \u05de\u05d5\u05e0\u05d8\u05e8\u05d9\u05d0\u05dc \u05d4\u05d5\u05d0 \u05e9\u05d9\u05e8\u05d5\u05ea \u05d4\u05d7\u05d9\u05e8\u05d5\u05dd \u05d4\u05e7\u05d4\u05d9\u05dc\u05ea\u05d9. \u05dc\u05d0 \u05d0\u05e6\u05d8\u05d8 \u05de\u05e1\u05e4\u05e8 \u05d8\u05dc\u05e4\u05d5\u05df \u05de\u05d4\u05d6\u05d9\u05db\u05e8\u05d5\u05df. \u05d9\u05e9 \u05dc\u05d4\u05e9\u05ea\u05de\u05e9 \u05d1\u05d0\u05ea\u05e8 \u05d4\u05e8\u05e9\u05de\u05d9.',
    yi:'\u05d0\u05d5\u05d9\u05d1 \u05e2\u05e1 \u05d0\u05d9\u05d6 \u05d0 \u05dc\u05e2\u05d1\u05e0\u05e1\u05be\u05d2\u05e2\u05e4\u05d0\u05e8, \u05e8\u05d5\u05e4\u05d8 \u05e2\u05e8\u05e9\u05d8 911.\n\n\u05d4\u05e6\u05dc\u05d4 \u05de\u05d0\u05e0\u05d8\u05e8\u05e2\u05d0\u05dc \u05d0\u05d9\u05d6 \u05d3\u05e2\u05e8 \u05e7\u05d4\u05d9\u05dc\u05d4\u05be\u05e1\u05e2\u05e8\u05d5\u05d5\u05d9\u05e1 \u05e4\u05d0\u05e8 \u05de\u05e2\u05d3\u05d9\u05e6\u05d9\u05e0\u05d9\u05e9\u05e2 \u05e0\u05d5\u05d9\u05d8\u05e4\u05d0\u05dc\u05df. \u05d0\u05d9\u05da \u05d5\u05d5\u05e2\u05dc \u05e0\u05d9\u05e9\u05d8 \u05d6\u05d0\u05d2\u05df \u05e7\u05d9\u05d9\u05df \u05d8\u05e2\u05dc\u05e2\u05e4\u05d0\u05df \u05e0\u05d5\u05de\u05e2\u05e8 \u05e4\u05d5\u05df \u05d6\u05db\u05e8\u05d5\u05df. \u05e0\u05d5\u05e6\u05d8 \u05d3\u05d9 \u05d0\u05e4\u05d9\u05e6\u05d9\u05e2\u05dc\u05e2 \u05d5\u05d5\u05e2\u05d1\u05d6\u05d9\u05d9\u05d8\u05dc \u05e6\u05d5 \u05d1\u05d0\u05e7\u05d5\u05de\u05e2\u05df \u05d3\u05e2\u05dd \u05e8\u05d9\u05db\u05d8\u05d9\u05d2\u05df \u05e0\u05d5\u05de\u05e2\u05e8.'
  }, L);
  // A "Call" button appears only if an admin has entered a verified number.
  // emergencyNumbers is empty by design, so today there is no call action -
  // which is correct: a wrong emergency number is worse than none.
  const H = ASK_HATZOLAH_RECORD;
  r.actions = [];
  (H.emergencyNumbers || []).forEach(n=>{
    r.actions.push({ label: askT({en:'Call ' + H.organization, fr:'Appeler ' + H.organization,
                                  he:'\u05d4\u05ea\u05e7\u05e9\u05e8\u05d5 \u05dc' + H.organization,
                                  yi:'\u05e8\u05d5\u05e4\u05d8 ' + H.organization}, L),
                     url:'tel:' + String(n).replace(/[^0-9+]/g,''), kind:'phone' });
  });
  r.actions.push({ label: askT({en:H.organization + ' Website', fr:'Site de ' + H.organization,
                                he:'\u05d0\u05ea\u05e8 ' + H.organization,
                                yi:H.organization + ' \u05d5\u05d5\u05e2\u05d1\u05d6\u05d9\u05d9\u05d8\u05dc'}, L), url:H.website, kind:'link' });
  if(H.mapUrl) r.actions.push({ label: askT({en:'View Map', fr:'Voir la carte', he:'\u05de\u05e4\u05d4', yi:'\u05d6\u05e2\u05d8 \u05d3\u05d9 \u05de\u05d0\u05e4\u05e2'}, L), url:H.mapUrl, kind:'map' });
  r.sources = askSortSources([{ name:H.organization, url:H.website, type:'Emergency',
                                authoritative:true, timeSensitive:false,
                                serviceArea:H.serviceArea, lastVerified:H.lastVerified }]);
  return r;
}

