/* ---------- CJHQ's own contact details ----------
   Read from the values already published on the contact page. This is CJHQ's
   OWN contact information and must never be confused with a partner
   organization: askOrganizations answers about partners, this answers about
   CJHQ. A partner's number is never CJHQ's number and vice versa. */
const ASK_CJHQ_CONTACT = {
  phone: '(514) 819-9440',
  email: 'info@cjhq.org',
  address: '1040 Van Horne Ave, Outremont, QC'
};

/* "How do I reach CJHQ" used to fall all the way through to a decline, which
   is a poor answer from CJHQ's own assistant about CJHQ itself. */
const ASK_CONTACT_RE = new RegExp([
  'contact (?:the )?cjhq', 'reach (?:the )?cjhq', 'cjhq(?:\'s)? (?:phone|number|email|office|address)',
  'contact (?:the )?office', 'reach (?:the )?office', 'where is (?:the )?(?:cjhq )?office',
  'speak to someone', 'talk to someone', 'someone (?:to )?call me',
  'question for cjhq', 'help from cjhq', 'someone help me at cjhq',
  'who do i contact at cjhq', 'contacter (?:le )?cjhq', 'joindre (?:le )?cjhq',
  'num\u00e9ro (?:du|de) cjhq', 'courriel (?:du|de) cjhq', 'parler \u00e0 quelqu\'un',
  '\u05dc\u05d9\u05e6\u05d5\u05e8 \u05e7\u05e9\u05e8 \u05e2\u05dd cjhq', '\u05d4\u05d8\u05dc\u05e4\u05d5\u05df \u05e9\u05dc cjhq', '\u05dc\u05d3\u05d1\u05e8 \u05e2\u05dd \u05de\u05d9\u05e9\u05d4\u05d5'
].join('|'), 'i');

function askContactCjhq(q){
  if(!ASK_CONTACT_RE.test(String(q || ''))) return null;
  const r = askAnswerShape();
  const L = askDetectLanguage(q); r.lang = L;
  r.handler = 'Contact CJHQ';
  r.handled = true;
  const C = ASK_CJHQ_CONTACT;
  r.answer = askT({
    en:'You can reach CJHQ at ' + C.phone + ' or ' + C.email + '. The office is at ' + C.address + '. The contact page has the full details and a message form.',
    fr:'Vous pouvez joindre le CJHQ au ' + C.phone + ' ou \u00e0 ' + C.email + '. Le bureau est au ' + C.address + '. La page Contact contient tous les d\u00e9tails et un formulaire.',
    he:'\u05e0\u05d9\u05ea\u05df \u05dc\u05d9\u05e6\u05d5\u05e8 \u05e7\u05e9\u05e8 \u05e2\u05dd CJHQ \u05d1\u05d8\u05dc\u05e4\u05d5\u05df ' + C.phone + ' \u05d0\u05d5 \u05d1\u05d3\u05d5\u05d0\u05f4\u05dc ' + C.email + '. \u05d4\u05de\u05e9\u05e8\u05d3 \u05e0\u05de\u05e6\u05d0 \u05d1-' + C.address + '. \u05d1\u05d3\u05e3 \u05d4\u05e7\u05e9\u05e8 \u05d9\u05e9 \u05d0\u05ea \u05db\u05dc \u05d4\u05e4\u05e8\u05d8\u05d9\u05dd \u05d5\u05d8\u05d5\u05e4\u05e1 \u05e4\u05e0\u05d9\u05d9\u05d4.',
    yi:'\u05d0\u05d9\u05e8 \u05e7\u05e2\u05e0\u05d8 \u05e0\u05d5\u05d7\u05df \u05de\u05d9\u05d8 CJHQ \u05d1\u05d9\u05d9\u05dd ' + C.phone + ' \u05d0\u05d3\u05e2\u05e8 ' + C.email + '. \u05d3\u05e2\u05e8 \u05d0\u05e4\u05d9\u05e1 \u05d0\u05d9\u05d6 \u05d1\u05d9\u05d9 ' + C.address + '. \u05d3\u05e2\u05e8 \u05e7\u05d0\u05e0\u05d8\u05d0\u05e7\u05d8 \u05d1\u05dc\u05d0\u05d8 \u05d4\u05d0\u05d8 \u05d3\u05d9 \u05e4\u05d5\u05dc\u05e2 \u05e4\u05e8\u05d8\u05d9\u05dd.'
  }, L);
  r.actions = [{ label: askT({en:'Contact CJHQ', fr:'Contacter le CJHQ', he:'\u05e6\u05d5\u05e8 \u05e7\u05e9\u05e8', yi:'\u05e7\u05d0\u05e0\u05d8\u05d0\u05e7\u05d8'}, L), url:'/contact', kind:'internal' }];
  r.sources = [{ name:'CJHQ Contact', url:'https://cjhq.org/contact', type:'CJHQ',
                 authoritative:true, timeSensitive:false, lastUpdated:'' }];
  return r;
}

/* ---------- child / minor travel ----------
   Compound intent. "What do I need to send my 12-year-old to New York alone?"
   previously matched nothing at all - the words that carry the meaning (child,
   alone, New York) are not resource keywords, so the matcher saw noise.

   This does NOT answer the question from model knowledge. It names the separate
   requirements so the person knows they are separate - travel document, parental
   consent, border entry, and the airline's own unaccompanied-minor policy are
   four different things and satisfying one does not satisfy the others - and
   hands over the CJHQ resources that exist for each. Airline policy is
   explicitly flagged as something CJHQ does not hold. */
const ASK_CHILD_RE = /\b(child|children|kid|kids|minor|son|daughter|toddler|\d{1,2}[ -]?year[ -]?old|12 ?yo|13 ?yo)\b|\benfant\b|\bmineur\b|\bfils\b|\bfille\b|\u05d9\u05dc\u05d3|\u05d9\u05dc\u05d3\u05d4|\u05e7\u05d8\u05d9\u05df|\u05e7\u05d9\u05e0\u05d3/i;
// Deliberately does NOT include a bare "travel": "Child travel consent
// letter" is someone naming a resource, and that belongs to the matcher, not
// to a four-part explainer. What fires this handler is a travel SITUATION -
// alone, without a parent, crossing a border, flying, international.
const ASK_CHILD_TRAVEL_RE = /fly|flying|flight|cross(?:ing)? the border|\bborder\b|abroad|international|\balone\b|without (?:me|both|a parent|parents)|unaccompanied|another family|by (?:him|her)self|voyage seul|fronti\u00e8re|\u05dc\u05d1\u05d3|\u05d2\u05d1\u05d5\u05dc|\u05d8\u05d9\u05e1\u05d4/i;

function askChildTravel(q){
  const s = String(q || '');
  if(!ASK_CHILD_RE.test(s) || !ASK_CHILD_TRAVEL_RE.test(s)) return null;
  const r = askAnswerShape();
  const L = askDetectLanguage(s); r.lang = L;
  r.handler = 'Child Travel';
  r.handled = true;
  r.timeSensitive = true;

  r.answer = askT({
    en:'A child travelling without both parents has four separate requirements, and meeting one does not cover the others:\n- Travel document: the child needs their own passport or accepted document.\n- Parental consent: a signed consent letter from the non-travelling parent(s).\n- Border entry: the destination country decides what it accepts at the border.\n- Airline policy: if the child flies, the airline sets its own unaccompanied-minor rules, which CJHQ does not hold - check directly with the airline.\nCJHQ has resources for the first two below. Confirm the border and airline requirements close to the travel date, since both change.',
    fr:'Un enfant qui voyage sans ses deux parents doit satisfaire quatre exigences distinctes; en remplir une ne remplace pas les autres\u00a0:\n- Document de voyage\u00a0: l\u2019enfant a besoin de son propre passeport ou d\u2019un document accept\u00e9.\n- Consentement parental\u00a0: une lettre de consentement sign\u00e9e par le ou les parents qui ne voyagent pas.\n- Entr\u00e9e \u00e0 la fronti\u00e8re\u00a0: le pays de destination d\u00e9cide de ce qu\u2019il accepte.\n- Politique de la compagnie a\u00e9rienne\u00a0: si l\u2019enfant prend l\u2019avion, la compagnie fixe ses propres r\u00e8gles pour les mineurs non accompagn\u00e9s; le CJHQ ne les d\u00e9tient pas \u2014 v\u00e9rifiez directement aupr\u00e8s d\u2019elle.\nLe CJHQ a des ressources pour les deux premi\u00e8res ci-dessous. Confirmez les exigences de la fronti\u00e8re et de la compagnie peu avant le d\u00e9part, car elles changent.',
    he:'\u05d9\u05dc\u05d3 \u05d4\u05e0\u05d5\u05e1\u05e2 \u05dc\u05dc\u05d0 \u05e9\u05e0\u05d9 \u05d4\u05d5\u05e8\u05d9\u05d5 \u05e6\u05e8\u05d9\u05da \u05dc\u05e2\u05de\u05d5\u05d3 \u05d1\u05d0\u05e8\u05d1\u05e2 \u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05e0\u05e4\u05e8\u05d3\u05d5\u05ea:\n- \u05de\u05e1\u05de\u05da \u05e0\u05e1\u05d9\u05e2\u05d4: \u05d3\u05e8\u05db\u05d5\u05df \u05de\u05e9\u05dc\u05d5 \u05d0\u05d5 \u05de\u05e1\u05de\u05da \u05de\u05d0\u05d5\u05e9\u05e8.\n- \u05d4\u05e1\u05db\u05de\u05ea \u05d4\u05d5\u05e8\u05d9\u05dd: \u05de\u05db\u05ea\u05d1 \u05d4\u05e1\u05db\u05de\u05d4 \u05d7\u05ea\u05d5\u05dd.\n- \u05db\u05e0\u05d9\u05e1\u05d4 \u05d1\u05d2\u05d1\u05d5\u05dc: \u05de\u05d3\u05d9\u05e0\u05ea \u05d4\u05d9\u05e2\u05d3 \u05de\u05d7\u05dc\u05d9\u05d8\u05d4 \u05de\u05d4 \u05d4\u05d9\u05d0 \u05de\u05e7\u05d1\u05dc\u05ea.\n- \u05de\u05d3\u05d9\u05e0\u05d9\u05d5\u05ea \u05d7\u05d1\u05e8\u05ea \u05d4\u05ea\u05e2\u05d5\u05e4\u05d4: \u05dc-CJHQ \u05d0\u05d9\u05df \u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05e2 \u05d4\u05d6\u05d4 \u2014 \u05d9\u05e9 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05de\u05d5\u05dc \u05d7\u05d1\u05e8\u05ea \u05d4\u05ea\u05e2\u05d5\u05e4\u05d4.\n\u05dc-CJHQ \u05d9\u05e9 \u05de\u05e9\u05d0\u05d1\u05d9\u05dd \u05dc\u05e9\u05ea\u05d9 \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d5\u05ea. \u05d9\u05e9 \u05dc\u05d0\u05de\u05ea \u05e1\u05de\u05d5\u05da \u05dc\u05e0\u05e1\u05d9\u05e2\u05d4.',
    yi:'\u05d0 \u05e7\u05d9\u05e0\u05d3 \u05d5\u05d5\u05d0\u05e1 \u05e8\u05d9\u05d9\u05d6\u05d8 \u05d0\u05df \u05d1\u05d9\u05d9\u05d3\u05e2 \u05e2\u05dc\u05d8\u05e2\u05e8\u05df \u05d3\u05d0\u05e8\u05e3 \u05d4\u05d0\u05d1\u05df \u05e4\u05d9\u05e8 \u05d1\u05d0\u05d6\u05d5\u05e0\u05d3\u05e2\u05e8\u05e2 \u05d6\u05d0\u05db\u05df:\n- \u05e8\u05d9\u05d9\u05d6\u05be\u05d3\u05d0\u05e7\u05d5\u05de\u05e2\u05e0\u05d8: \u05d0\u05df \u05d0\u05d9\u05d9\u05d2\u05e2\u05e0\u05e2\u05dd \u05e4\u05d0\u05e1\u05e4\u05d0\u05e8\u05d8.\n- \u05e2\u05dc\u05d8\u05e2\u05e8\u05e0\u05e1 \u05d4\u05e1\u05db\u05de\u05d4: \u05d0 \u05d0\u05d5\u05e0\u05d8\u05e2\u05e8\u05d2\u05e2\u05e9\u05e8\u05d9\u05d1\u05df \u05d1\u05e8\u05d9\u05f4\u05e3.\n- \u05d2\u05e8\u05e2\u05e0\u05d9\u05e5: \u05d3\u05e2\u05e8 \u05dc\u05d0\u05e0\u05d3 \u05d1\u05d0\u05e9\u05dc\u05d9\u05e1\u05d8 \u05d5\u05d5\u05d0\u05e1 \u05e2\u05e8 \u05e0\u05e2\u05de\u05d8 \u05d0\u05df.\n- \u05e2\u05e8\u05dc\u05d0\u05d9\u05df \u05e8\u05e2\u05d2\u05dc\u05e2\u05df: CJHQ \u05d4\u05d0\u05d8 \u05d3\u05d0\u05e1 \u05e0\u05d9\u05e9\u05d8 \u2014 \u05e4\u05e8\u05e2\u05d2\u05d8 \u05d1\u05d9\u05d9 \u05d3\u05e2\u05e8 \u05e2\u05e8\u05dc\u05d0\u05d9\u05df.\nCJHQ \u05d4\u05d0\u05d8 \u05e8\u05e2\u05e1\u05d5\u05e8\u05e1\u05df \u05e4\u05d0\u05e8 \u05d3\u05d9 \u05e2\u05e8\u05e9\u05d8\u05e2 \u05e6\u05d5\u05d5\u05d9\u05d9.'
  }, L);

  // Attach only the CJHQ resources that exist for these requirements.
  const picks = [];
  const consent = askMatchResources('child travel consent letter', 1);
  const passport = askMatchResources('child passport application', 1);
  if(consent.length)  picks.push(consent[0]);
  if(passport.length) picks.push(passport[0]);
  r.actions = picks.map(h => ({
    label: (L === 'fr' && h.item.fr) ? h.item.fr : h.item.en,
    url: h.item.internalPage ? ('/' + h.item.internalPage) : ('/resources/' + h.item.slug),
    kind:'internal'
  }));
  r.sources = picks.map(h => ({
    name: h.item.en, url:'https://cjhq.org/resources/' + h.item.slug,
    type:'CJHQ Resource', authoritative:true, timeSensitive:false, lastUpdated:''
  }));
  return r;
}

/* Reads the optional verified fields WHEN they exist on a partner record. None
   of them are populated today - PARTNERS_DATA carries name, logo, dimensions
   and url, nothing more - and this deliberately populates none of them. The
   point is that the day CJHQ adds a verified phone or email to a record, the
   assistant starts using it with no code change and no second database. */
/* CONTACT SCHEMA - the fields a partner record may carry once staff have
   entered them. Every one ships empty.

     phone              a published general number, purpose not classified
     emergencyPhone     ONLY where the organization itself calls it an
                        emergency/urgent line
     nonEmergencyPhone  ONLY where the purpose is explicitly non-urgent
     additionalPhone    any further published line
     email, address, website, description, services[], aliases[]
     hours, languages   only where explicitly published
     contactSource      where the information came from
     contactVerified    false until a CJHQ staff member confirms it
     contactVerifiedDate

   phone is NEVER copied into emergencyPhone. A general office line presented
   as an emergency number is the single most dangerous thing this directory
   could contain: someone would call it during an emergency and get voicemail.
   The three fields stay separate in the data, in the editor and in the answer.

   contacts is an optional map of { [organization name]: {...fields} }. The
   website passes the Firestore partner_overrides cache; the WhatsApp bridge
   passes the same records it fetched itself. The core stores nothing. */
/* ---------- name normalization + fuzzy organization matching ----------
   Two real failures this addresses, both found by testing rather than assumed:

   1. "contact refua vchesed" returned nothing. The matcher was a raw substring
      test, so a dropped 'h' and a missing space defeated it even though the
      organization is in CJHQ's own data.

   2. "passprt renewal" matched an ORGANIZATION. "renewal" is a whole word in
      "Renewal Canada", and a substring test cannot tell a name from an ordinary
      English word. That is the false positive section 9 warns about, and it was
      live before this change.

   The approach: normalize both sides, match on word sequences rather than raw
   substrings, and only fall back to edit distance for candidates that look like
   names. Fuzzy matching NEVER alters what is returned - it only decides WHICH
   verified record to read. Every field still comes from that record.          */

function askNormalizeName(v){
  return String(v == null ? '' : v)
    .toLowerCase()
    .replace(/[\u2018\u2019\u02bc\u0060\u00b4]/g, "'")   // curly/backtick -> straight
    .replace(/['`]/g, '')                                 // then drop apostrophes entirely
    .replace(/[^a-z0-9\u0590-\u05FF]+/g, ' ')             // punctuation/hyphens -> space
    .replace(/\s+/g, ' ')
    .trim();
}

/* MAINTAINED SAFETY LIST - REVIEW WHENEVER A PARTNER IS ADDED.

   These are words that appear inside an organization's name but are also
   ordinary vocabulary. A single-token match on one of them is not evidence of
   anything: "renewal" is a word in "Renewal Canada" and also in "passport
   renewal", and before this list existed the question "passprt renewal" was
   answered with an organization record instead of the passport resource.

   Multi-word matches are unaffected - "renewal canada" still resolves normally,
   because only a lone token is rejected.

   THIS LIST IS NOT DERIVED AUTOMATICALLY. When a new CJHQ partner or
   organization is added to PARTNERS_DATA, check whether any single word of its
   name is also a word someone might reasonably type in an unrelated question -
   for example a name containing "Health", "Family", "Travel", "Centre" or
   "Support". If so, add that word here. Skipping this step reintroduces the
   false positive for the new organization only, which is exactly the kind of
   bug that hides: everything else keeps working. */
const ASK_ORG_GENERIC = new Set(['renewal','canada','montreal','tosh','lifeline',
  'interstate','olam','centre','center','council','community','services','service']);

function askLevenshtein(a, b){
  if(a === b) return 0;
  const m = a.length, n = b.length;
  if(!m) return n;
  if(!n) return m;
  let prev = new Array(n + 1);
  for(let j = 0; j <= n; j++) prev[j] = j;
  for(let i = 1; i <= m; i++){
    const cur = [i];
    for(let j = 1; j <= n; j++){
      cur[j] = Math.min(prev[j] + 1, cur[j-1] + 1, prev[j-1] + (a[i-1] === b[j-1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[n];
}

function askSimilarity(a, b){
  const longest = Math.max(a.length, b.length);
  if(!longest) return 0;
  return 1 - (askLevenshtein(a, b) / longest);
}

/* Confidence tiers, chosen against the real 16-name dataset rather than picked
   out of the air:
     >= 0.86  one edit in a name of ~7+ characters. "refua vchesed" vs
              "refuah vchesed" scores 0.93; "chaverim" vs "chavivim" - two
              genuinely different organizations - scores 0.75 and must NOT
              auto-resolve.
     0.78-0.86 close enough to mean something, not close enough to act on.
              Ask which one.
     < 0.78   no match. The existing no-answer behaviour applies.              */
const ASK_ORG_FUZZY_HIGH = 0.86;
const ASK_ORG_FUZZY_ASK  = 0.78;

/* Candidate name phrases from the question: every run of 1-4 consecutive
   words. Fuzzy comparison is only ever done against these, never against the
   whole sentence, so a typo in a common word cannot drift into a name match. */
function askNameCandidates(norm){
  const w = norm.split(' ').filter(Boolean);
  const out = [];
  for(let n = 4; n >= 1; n--){
    for(let i = 0; i + n <= w.length; i++) out.push(w.slice(i, i + n).join(' '));
  }
  return out;
}

function askOrgRegistry(contacts){
  const raw = (typeof PARTNERS_DATA !== 'undefined') ? PARTNERS_DATA : [];
  const extra = contacts || (typeof PARTNER_OVERRIDES_CACHE !== 'undefined' ? PARTNER_OVERRIDES_CACHE : null) || {};
  return raw.map(p => Object.assign({}, p, extra[(p.alt || p.name || '').trim()] || {})).map(p => ({
    name:        (p.alt || p.name || '').trim(),
    url:         p.url || '',
    phone:       p.phone || '',
    emergencyPhone: p.emergencyPhone || '',
    email:       p.email || '',
    description: p.description || '',
    nonEmergencyPhone: p.nonEmergencyPhone || '',
    additionalPhone:   p.additionalPhone || '',
    address:     p.address || '',
    hours:       p.hours || '',
    languages:   p.languages || '',
    services:    Array.isArray(p.services) ? p.services : [],
    aliases:     Array.isArray(p.aliases) ? p.aliases : [],
    contactSource:      p.contactSource || '',
    contactVerified:    p.contactVerified === true,
    contactVerifiedDate: p.contactVerifiedDate || ''
  })).filter(o => o.name);

}

/* Completeness state for the admin list. Deliberately does NOT treat a missing
   emergency number as incomplete - most organizations do not have one, and
   flagging that as a gap would push someone toward inventing one. */
function askOrgContactState(o){
  const hasAny = !!(o.phone || o.emergencyPhone || o.nonEmergencyPhone || o.email);
  if(!hasAny) return 'none';
  if(o.contactVerified) return 'verified';
  return 'pending';
}

function askOrgMatch(q, contacts){
  const norm = askNormalizeName(q);
  const orgs = askOrgRegistry(contacts);
  const found = [];

  // Pass 1 - exact, on normalized whole-word sequences. A single-token alias
  // that is ordinary vocabulary ("renewal") is not accepted on its own.
  orgs.forEach(o => {
    const key = o.name.toLowerCase();
    const aliases = [o.name].concat(ASK_ORG_ALIASES[key] || []).concat(o.aliases || []);
    const hit = aliases.some(a => {
      const na = askNormalizeName(a);
      if(!na) return false;
      if(na.indexOf(' ') < 0 && ASK_ORG_GENERIC.has(na)) return false;
      return (' ' + norm + ' ').indexOf(' ' + na + ' ') >= 0;
    });
    if(hit) found.push(o);
  });
  if(found.length) return found;

  // Pass 2 - fuzzy, and only against name-shaped candidates. Short candidates
  // are excluded: edit distance on a 4-letter word matches almost anything.
  const cands = askNameCandidates(norm).filter(c => c.length >= 6);
  let best = null, bestScore = 0, second = 0;
  orgs.forEach(o => {
    const key = o.name.toLowerCase();
    const aliases = [o.name].concat(ASK_ORG_ALIASES[key] || []).concat(o.aliases || []);
    aliases.forEach(a => {
      const na = askNormalizeName(a);
      if(na.length < 6) return;                       // too short to fuzz safely
      if(na.indexOf(' ') < 0 && ASK_ORG_GENERIC.has(na)) return;
      cands.forEach(c => {
        const sc = askSimilarity(c, na);
        if(sc > bestScore){ second = bestScore; bestScore = sc; best = o; }
        else if(sc > second && o !== best){ second = sc; }
      });
    });
  });
  if(best && bestScore >= ASK_ORG_FUZZY_HIGH && bestScore - second >= 0.05) return [best];
  if(best && bestScore >= ASK_ORG_FUZZY_ASK){
    // Medium confidence: hand back the candidates so the caller can ask rather
    // than resolve. Marked so askOrganizations knows not to answer outright.
    const near = orgs.filter(o => {
      const key = o.name.toLowerCase();
      const aliases = [o.name].concat(ASK_ORG_ALIASES[key] || []).concat(o.aliases || []);
      return aliases.some(a => {
        const na = askNormalizeName(a);
        return na.length >= 6 && cands.some(c => askSimilarity(c, na) >= ASK_ORG_FUZZY_ASK);
      });
    });
    if(near.length){ near.__uncertain = true; return near; }
  }
  if(found.length) return found;
  // No name matched - try the service map, then resolve those names in the
  // real registry so a renamed or removed partner cannot linger here.
  const svc = ASK_ORG_SERVICES.find(x => x.match.test(String(q || '')));
  if(!svc) return [];
  return svc.orgs
    .map(n => orgs.find(o => o.name.toLowerCase() === n.toLowerCase()))
    .filter(Boolean);
}

const ASK_ORG_PHONE_ASK = /phone|number|call|t\u00e9l\u00e9phone|num\u00e9ro|appeler|\u05d8\u05dc\u05e4\u05d5\u05df|\u05de\u05e1\u05e4\u05e8|\u05dc\u05d4\u05ea\u05e7\u05e9\u05e8|\u05e0\u05d5\u05de\u05e2\u05e8|\u05e8\u05d5\u05e4\u05df/i;

function askOrganizations(q, opts){
  const hits = askOrgMatch(q, opts && opts.orgContacts);
  if(!hits.length) return null;
  const r = askAnswerShape();
  const L = askDetectLanguage(q); r.lang = L;
  r.handler = 'Organizations';
  r.handled = true;

  // Medium-confidence fuzzy match: name the candidates and ask, rather than
  // answering confidently about whichever scored marginally higher. Contact
  // details are exactly the wrong thing to guess at.
  if(hits.__uncertain){
    const names = hits.slice(0, 3).map(o => o.name);
    r.handled = false;
    r.answer = askT({
      en:'Did you mean ' + names.join(' or ') + '? Tell me which one and I can give you what CJHQ has on file.',
      fr:'Vouliez-vous dire ' + names.join(' ou ') + '\u00a0? Indiquez-moi lequel et je vous donnerai ce que le CJHQ a au dossier.',
      he:'\u05d4\u05ea\u05db\u05d5\u05d5\u05e0\u05ea\u05dd \u05dc-' + names.join(' \u05d0\u05d5 ') + '? \u05e6\u05d9\u05d9\u05e0\u05d5 \u05d0\u05d9\u05d6\u05d4 \u05d5\u05d0\u05de\u05e1\u05d5\u05e8 \u05de\u05d4 \u05e9\u05d9\u05e9 \u05dc-CJHQ.',
      yi:'\u05de\u05d9\u05d9\u05e0\u05d8 \u05d0\u05d9\u05e8 ' + names.join(' \u05d0\u05d3\u05e2\u05e8 ') + '? \u05d6\u05d0\u05d2\u05d8 \u05de\u05d9\u05e8 \u05d5\u05d5\u05e2\u05dc\u05db\u05e2\u05e8 \u05d0\u05d5\u05df \u05d0\u05d9\u05da \u05d5\u05d5\u05e2\u05dc \u05d6\u05d0\u05d2\u05df \u05d5\u05d5\u05d0\u05e1 CJHQ \u05d4\u05d0\u05d8.'
    }, L);
    r.actions = hits.slice(0, 3).filter(o => o.url).map(o => ({ label:o.name, url:o.url, kind:'link' }));
    return r;
  }

  const named = hits.slice(0, 3);
  const list = named.map(o => o.name).join(', ');
  const wantsPhone = ASK_ORG_PHONE_ASK.test(String(q || ''));
  // ONLY verified data is ever spoken. A record that staff have entered but
  // not confirmed is invisible to users - it exists so staff can review it,
  // not so the assistant can hedge with it. Research status, sources and the
  // pending flag never appear in an answer.
  const wantsNonEmergencyFirst = /non[- ]?emergenc|not (?:an )?emergenc|regular (?:line|number)|non[- ]?urgent/i.test(String(q || ''));
  const wantsEmergency = !wantsNonEmergencyFirst && /emergenc|urgent|urgence|\u05d7\u05d9\u05e8\u05d5\u05dd|\u05d3\u05d7\u05d5\u05e3/i.test(String(q || ''));
  const wantsNonEmergency = /non[- ]?emergenc|not (?:an )?emergenc|regular (?:line|number)|non[- ]?urgent/i.test(String(q || ''));
  const verified = named.filter(o => o.contactVerified &&
    (o.phone || o.emergencyPhone || o.nonEmergencyPhone));
  if(wantsPhone && verified.length){
    r.answer = verified.map(o => {
      // Answer the line that was actually asked for. Never substitute one
      // category for another: if someone asks for the emergency number and
      // CJHQ only holds a general one, say so rather than handing over the
      // general line as though it were the emergency line.
      if(wantsEmergency){
        return o.emergencyPhone
          ? o.name + ' (emergency): ' + o.emergencyPhone
          : o.name + ': CJHQ does not have a verified emergency number on file'
            + (o.phone ? '. The verified general number is ' + o.phone + '.' : '.');
      }
      if(wantsNonEmergency){
        return o.nonEmergencyPhone
          ? o.name + ' (non-emergency): ' + o.nonEmergencyPhone
          : o.name + ': CJHQ does not have a verified non-emergency number on file'
            + (o.phone ? '. The verified general number is ' + o.phone + '.' : '.');
      }
      const lines = [];
      if(o.phone) lines.push(o.phone);
      if(o.nonEmergencyPhone) lines.push(o.nonEmergencyPhone + ' (non-emergency)');
      if(o.emergencyPhone) lines.push(o.emergencyPhone + ' (emergency)');
      if(o.email) lines.push(o.email);
      return o.name + ': ' + lines.join(' / ');
    }).join('\n');
    r.actions = named.filter(o => o.url).map(o => ({ label:o.name, url:o.url, kind:'link' }));
    r.sources = named.filter(o => o.url).map(o => ({
      name:o.name, url:o.url, type:'Community organization',
      authoritative:true, timeSensitive:false, lastUpdated:'' }));
    return r;
  }

  // CJHQ publishes the organization and its website. It does not publish
  // contact numbers, so a phone question gets an honest answer and the
  // official site, which is where the current number actually lives.
  // Reached when there is no verified number. The claim is precise: CJHQ does
  // not have one on file. It is NOT a claim that the organization has no
  // phone number, and it is not "we couldn't find anything".
  const phoneNote = wantsPhone ? askT({
    en:' CJHQ does not hold a verified phone number for ' + (named.length === 1 ? 'it' : 'these') + ', and I will not quote one from anywhere else - numbers change and a wrong one costs someone time in an emergency. The official site below has the current contact details.',
    fr:' Le CJHQ ne d\u00e9tient pas de num\u00e9ro de t\u00e9l\u00e9phone v\u00e9rifi\u00e9, et je n\u2019en citerai pas un provenant d\u2019ailleurs \u2014 les num\u00e9ros changent et un mauvais num\u00e9ro co\u00fbte du temps en situation d\u2019urgence. Le site officiel ci-dessous contient les coordonn\u00e9es \u00e0 jour.',
    he:' \u05dc-CJHQ \u05d0\u05d9\u05df \u05de\u05e1\u05e4\u05e8 \u05d8\u05dc\u05e4\u05d5\u05df \u05de\u05d0\u05d5\u05de\u05ea, \u05d5\u05dc\u05d0 \u05d0\u05e6\u05d8\u05d8 \u05de\u05e1\u05e4\u05e8 \u05de\u05de\u05e7\u05d5\u05e8 \u05d0\u05d7\u05e8 \u2014 \u05de\u05e1\u05e4\u05e8\u05d9\u05dd \u05de\u05e9\u05ea\u05e0\u05d9\u05dd \u05d5\u05de\u05e1\u05e4\u05e8 \u05e9\u05d2\u05d5\u05d9 \u05e2\u05d5\u05dc\u05d4 \u05d6\u05de\u05df \u05d1\u05e9\u05e2\u05ea \u05d7\u05d9\u05e8\u05d5\u05dd. \u05d1\u05d0\u05ea\u05e8 \u05d4\u05e8\u05e9\u05de\u05d9 \u05e9\u05dc\u05d4\u05dc\u05df \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05e4\u05e8\u05d8\u05d9 \u05d4\u05e7\u05e9\u05e8 \u05d4\u05e2\u05d3\u05db\u05e0\u05d9\u05d9\u05dd.',
    yi:' CJHQ \u05d4\u05d0\u05d8 \u05e0\u05d9\u05e9\u05d8 \u05e7\u05d9\u05d9\u05df \u05d1\u05d0\u05e9\u05d8\u05e2\u05d8\u05d9\u05d2\u05d8\u05df \u05d8\u05e2\u05dc\u05e2\u05e4\u05d0\u05df \u05e0\u05d5\u05de\u05e2\u05e8, \u05d0\u05d5\u05df \u05d0\u05d9\u05da \u05d5\u05d5\u05e2\u05dc \u05e0\u05d9\u05e9\u05d8 \u05d6\u05d0\u05d2\u05df \u05d0\u05d9\u05d9\u05e0\u05e2\u05dd \u05e4\u05d5\u05df \u05d0\u05e0\u05d3\u05e2\u05e8\u05e9\u05d5\u05d5\u05d5. \u05d3\u05d9 \u05d0\u05e4\u05d9\u05e6\u05d9\u05e2\u05dc\u05e2 \u05d5\u05d5\u05e2\u05d1\u05d6\u05d9\u05d9\u05d8\u05dc \u05d3\u05d0 \u05d0\u05d5\u05e0\u05d8\u05df \u05d4\u05d0\u05d8 \u05d3\u05d9 \u05d9\u05e2\u05e6\u05d8\u05d9\u05d2\u05e2 \u05e4\u05e8\u05d8\u05d9\u05dd.'
  }, L) : '';

  r.answer = askT({
    en:(named.length === 1
        ? named[0].name + ' is one of the organizations CJHQ works with.'
        : 'CJHQ works with ' + list + '.') + phoneNote,
    fr:(named.length === 1
        ? named[0].name + ' fait partie des organismes avec lesquels le CJHQ collabore.'
        : 'Le CJHQ collabore avec ' + list + '.') + phoneNote,
    he:(named.length === 1
        ? named[0].name + ' \u05d4\u05d5\u05d0 \u05d0\u05d7\u05d3 \u05d4\u05d0\u05e8\u05d2\u05d5\u05e0\u05d9\u05dd \u05e9-CJHQ \u05e2\u05d5\u05d1\u05d3 \u05d0\u05d9\u05ea\u05dd.'
        : 'CJHQ \u05e2\u05d5\u05d1\u05d3 \u05e2\u05dd ' + list + '.') + phoneNote,
    yi:(named.length === 1
        ? named[0].name + ' \u05d0\u05d9\u05d6 \u05d0\u05d9\u05d9\u05e0\u05e2\u05e8 \u05e4\u05d5\u05df \u05d3\u05d9 \u05d0\u05e8\u05d2\u05d0\u05e0\u05d9\u05d6\u05d0\u05e6\u05d9\u05e2\u05e1 \u05d5\u05d5\u05d0\u05e1 CJHQ \u05d0\u05e8\u05d1\u05e2\u05d8 \u05de\u05d9\u05d8.'
        : 'CJHQ \u05d0\u05e8\u05d1\u05e2\u05d8 \u05de\u05d9\u05d8 ' + list + '.') + phoneNote
  }, L);

  r.actions = named.filter(o => o.url).map(o => ({ label:o.name, url:o.url, kind:'link' }));
  r.sources = named.filter(o => o.url).map(o => ({
    name:o.name, url:o.url, type:'Community organization',
    authoritative:true, timeSensitive:false, lastUpdated:''
  }));
  // A partner with no published site (2 of the 16) gets named, not linked.
  if(!r.actions.length){
    r.actions = [{ label: askT({en:'CJHQ Resource Centre', fr:'Centre de ressources CJHQ', he:'\u05de\u05e8\u05db\u05d6 \u05d4\u05de\u05e9\u05d0\u05d1\u05d9\u05dd', yi:'CJHQ \u05e8\u05e2\u05e1\u05d5\u05e8\u05e1 \u05e6\u05e2\u05e0\u05d8\u05e2\u05e8'}, L), url:'/resources', kind:'internal' }];
  }
  return r;
}

function askSpecialInfo(q){
  const s = String(q || '');
  if(!ASK_SPECIAL_ITEMS.test(s) || !ASK_SPECIAL_TRAVEL.test(s)) return null;
  if(typeof SPECIAL_INFO_COUNTRIES === 'undefined') return null;

  const r = askAnswerShape();
  const L = askDetectLanguage(s); r.lang = L;
  r.handler = 'Special Information';
  r.timeSensitive = true;

  const hit = ASK_SPECIAL_COUNTRY.find(c => c.match.test(s));
  const rec = hit ? SPECIAL_INFO_COUNTRIES.find(c => c.id === hit.id) : null;

  // No country named: say which ones CJHQ actually covers rather than guessing.
  if(!rec){
    r.handled = false;
    r.answer = askT({
      en:'That depends on the country you are travelling to, and the requirements differ by item and time of year. CJHQ holds verified travel information for Canada, the United States and the United Kingdom. Tell me the destination and I can give you what CJHQ has.',
      fr:'Cela d\u00e9pend du pays de destination, et les exigences varient selon l\u2019article et la p\u00e9riode de l\u2019ann\u00e9e. Le CJHQ dispose de renseignements v\u00e9rifi\u00e9s pour le Canada, les \u00c9tats-Unis et le Royaume-Uni. Indiquez la destination et je vous donnerai ce que le CJHQ a.',
      he:'\u05d6\u05d4 \u05ea\u05dc\u05d5\u05d9 \u05d1\u05de\u05d3\u05d9\u05e0\u05ea \u05d4\u05d9\u05e2\u05d3, \u05d5\u05d4\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05de\u05e9\u05ea\u05e0\u05d5\u05ea \u05dc\u05e4\u05d9 \u05d4\u05e4\u05e8\u05d9\u05d8 \u05d5\u05ea\u05e7\u05d5\u05e4\u05ea \u05d4\u05e9\u05e0\u05d4. \u05dc-CJHQ \u05d9\u05e9 \u05de\u05d9\u05d3\u05e2 \u05de\u05d0\u05d5\u05de\u05ea \u05e2\u05d1\u05d5\u05e8 \u05e7\u05e0\u05d3\u05d4, \u05d0\u05e8\u05d4"\u05d1 \u05d5\u05d1\u05e8\u05d9\u05d8\u05e0\u05d9\u05d4. \u05e6\u05d9\u05d9\u05e0\u05d5 \u05d0\u05ea \u05d4\u05d9\u05e2\u05d3 \u05d5\u05d0\u05de\u05e1\u05d5\u05e8 \u05de\u05d4 \u05e9\u05d9\u05e9 \u05dc-CJHQ.',
      yi:'\u05d3\u05d0\u05e1 \u05d4\u05e2\u05e0\u05d2\u05d8 \u05d0\u05e4\u05df \u05dc\u05d0\u05e0\u05d3 \u05d5\u05d5\u05d0\u05d5\u05d4\u05d9\u05df \u05d0\u05d9\u05e8 \u05e4\u05d0\u05e8\u05d8, \u05d0\u05d5\u05df \u05d3\u05d9 \u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05e2\u05e0\u05d3\u05e2\u05e8\u05df \u05d6\u05d9\u05da \u05dc\u05d5\u05d9\u05d8\u05df \u05d0\u05e8\u05d8\u05d9\u05e7\u05dc \u05d0\u05d5\u05df \u05e6\u05f4\u05d8 \u05e4\u05d5\u05df \u05d9\u05d0\u05e8. CJHQ \u05d4\u05d0\u05d8 \u05d1\u05d0\u05e9\u05d8\u05e2\u05d8\u05d9\u05d2\u05d8\u05e2 \u05d0\u05d9\u05e0\u05e4\u05d0\u05e8\u05de\u05d0\u05e6\u05d9\u05e2 \u05e4\u05d0\u05e8 \u05e7\u05d0\u05e0\u05d0\u05d3\u05e2, \u05d0\u05de\u05e2\u05e8\u05d9\u05e7\u05e2 \u05d0\u05d5\u05df \u05d1\u05e8\u05d9\u05d8\u05d0\u05e0\u05d9\u05e2. \u05d6\u05d0\u05d2\u05d8 \u05de\u05d9\u05e8 \u05d3\u05e2\u05dd \u05dc\u05d0\u05e0\u05d3 \u05d0\u05d5\u05df \u05d0\u05d9\u05da \u05d5\u05d5\u05e2\u05dc \u05d0\u05d9\u05d9\u05da \u05d6\u05d0\u05d2\u05df \u05d5\u05d5\u05d0\u05e1 CJHQ \u05d4\u05d0\u05d8.'
    }, L);
    return r;
  }

  const isFr = (L === 'fr');
  const name = isFr ? rec.name_fr : rec.name_en;
  const intro = isFr ? rec.intro_fr : rec.intro_en;
  const before = (isFr ? rec.before_fr : rec.before_en) || [];
  const warning = isFr ? rec.warning_fr : rec.warning_en;
  const links = (rec.official || []).filter(l => l && l.url);

  // Verified-but-empty is a real state: Israel and the EU carry no link and no
  // verification date. Saying so is the correct answer.
  if(!links.length || !rec.lastVerified){
    r.handled = false;
    r.answer = askT({
      en:'CJHQ does not currently have verified travel information for ' + name + ' on this. I am not going to describe an import rule that has not been checked against that country\u2019s own authority. Confirm the current requirement with the destination country\u2019s customs or agriculture authority before travelling.',
      fr:'Le CJHQ n\u2019a pas actuellement de renseignements v\u00e9rifi\u00e9s pour ' + name + ' \u00e0 ce sujet. Je ne d\u00e9crirai pas une r\u00e8gle d\u2019importation qui n\u2019a pas \u00e9t\u00e9 v\u00e9rifi\u00e9e aupr\u00e8s de l\u2019autorit\u00e9 du pays. Confirmez l\u2019exigence en vigueur aupr\u00e8s des douanes ou de l\u2019autorit\u00e9 agricole du pays de destination avant de voyager.',
      he:'\u05dc-CJHQ \u05d0\u05d9\u05df \u05db\u05e8\u05d2\u05e2 \u05de\u05d9\u05d3\u05e2 \u05de\u05d0\u05d5\u05de\u05ea \u05e2\u05d1\u05d5\u05e8 ' + name + ' \u05d1\u05e0\u05d5\u05e9\u05d0 \u05d6\u05d4. \u05dc\u05d0 \u05d0\u05ea\u05d0\u05e8 \u05db\u05dc\u05dc \u05d9\u05d1\u05d5\u05d0 \u05e9\u05dc\u05d0 \u05d0\u05d5\u05de\u05ea \u05de\u05d5\u05dc \u05d4\u05e8\u05e9\u05d5\u05ea \u05e9\u05dc \u05d0\u05d5\u05ea\u05d4 \u05de\u05d3\u05d9\u05e0\u05d4. \u05d9\u05e9 \u05dc\u05d0\u05de\u05ea \u05d0\u05ea \u05d4\u05d3\u05e8\u05d9\u05e9\u05d4 \u05d4\u05e0\u05d5\u05db\u05d7\u05d9\u05ea \u05de\u05d5\u05dc \u05d4\u05de\u05db\u05e1 \u05d0\u05d5 \u05e8\u05e9\u05d5\u05ea \u05d4\u05d7\u05e7\u05dc\u05d0\u05d5\u05ea \u05e9\u05dc \u05de\u05d3\u05d9\u05e0\u05ea \u05d4\u05d9\u05e2\u05d3 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e0\u05e1\u05d9\u05e2\u05d4.',
      yi:'CJHQ \u05d4\u05d0\u05d8 \u05d9\u05e2\u05e6\u05d8 \u05e0\u05d9\u05e9\u05d8 \u05e7\u05d9\u05d9\u05df \u05d1\u05d0\u05e9\u05d8\u05e2\u05d8\u05d9\u05d2\u05d8\u05e2 \u05e8\u05d9\u05d9\u05d6\u05be\u05d0\u05d9\u05e0\u05e4\u05d0\u05e8\u05de\u05d0\u05e6\u05d9\u05e2 \u05e4\u05d0\u05e8 ' + name + ' \u05d3\u05e2\u05e8\u05d5\u05d9\u05e3. \u05d0\u05d9\u05da \u05d5\u05d5\u05e2\u05dc \u05e0\u05d9\u05e9\u05d8 \u05d1\u05d0\u05e9\u05e8\u05d9\u05d9\u05d1\u05df \u05e7\u05d9\u05d9\u05df \u05d0\u05d9\u05de\u05e4\u05d0\u05e8\u05d8\u05be\u05e8\u05e2\u05d2\u05dc \u05d5\u05d5\u05d0\u05e1 \u05d0\u05d9\u05d6 \u05e0\u05d9\u05e9\u05d8 \u05d1\u05d0\u05e9\u05d8\u05e2\u05d8\u05d9\u05d2\u05d8 \u05d2\u05e2\u05d5\u05d5\u05d0\u05e8\u05df \u05d1\u05d9\u05d9 \u05d3\u05e2\u05e8 \u05de\u05d3\u05d9\u05e0\u05d4\u05f4\u05e1 \u05d0\u05d9\u05d9\u05d2\u05e2\u05e0\u05e2\u05e8 \u05e8\u05e9\u05d5\u05ea. \u05e4\u05d0\u05e8\u05d6\u05d9\u05db\u05e2\u05e8\u05d8 \u05d3\u05d9 \u05d9\u05e2\u05e6\u05d8\u05d9\u05d2\u05e2 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05d1\u05d9\u05d9 \u05d3\u05e2\u05dd \u05dc\u05d0\u05e0\u05d3\u05e1 \u05de\u05db\u05e1 \u05d0\u05d3\u05e2\u05e8 \u05dc\u05d0\u05e0\u05d5\u05d5\u05d9\u05e8\u05d8\u05e9\u05d0\u05e4\u05d8\u05be\u05e8\u05e9\u05d5\u05ea \u05e4\u05d0\u05e8 \u05d3\u05e2\u05e8 \u05e8\u05d9\u05d9\u05d6\u05e2.'
    }, L);
    return r;
  }

  r.handled = true;
  const lead = askT({
    en:'CJHQ travel information for ' + name + ':',
    fr:'Renseignements de voyage du CJHQ pour ' + name + '\u00a0:',
    he:'\u05de\u05d9\u05d3\u05e2 \u05e0\u05e1\u05d9\u05e2\u05d5\u05ea \u05e9\u05dc CJHQ \u05e2\u05d1\u05d5\u05e8 ' + name + ':',
    yi:'CJHQ \u05e8\u05d9\u05d9\u05d6\u05be\u05d0\u05d9\u05e0\u05e4\u05d0\u05e8\u05de\u05d0\u05e6\u05d9\u05e2 \u05e4\u05d0\u05e8 ' + name + ':'
  }, L);
  const checkNote = askT({
    en:'Requirements change and are enforced by the destination country, not by CJHQ. Confirm the current requirement with the official source below shortly before you travel.',
    fr:'Les exigences changent et sont appliqu\u00e9es par le pays de destination, non par le CJHQ. Confirmez l\u2019exigence en vigueur aupr\u00e8s de la source officielle ci-dessous peu avant votre d\u00e9part.',
    he:'\u05d4\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05de\u05e9\u05ea\u05e0\u05d5\u05ea \u05d5\u05e0\u05d0\u05db\u05e4\u05d5\u05ea \u05e2\u05dc \u05d9\u05d3\u05d9 \u05de\u05d3\u05d9\u05e0\u05ea \u05d4\u05d9\u05e2\u05d3, \u05dc\u05d0 \u05e2\u05dc \u05d9\u05d3\u05d9 CJHQ. \u05d9\u05e9 \u05dc\u05d0\u05de\u05ea \u05d0\u05ea \u05d4\u05d3\u05e8\u05d9\u05e9\u05d4 \u05d4\u05e0\u05d5\u05db\u05d7\u05d9\u05ea \u05d1\u05de\u05e7\u05d5\u05e8 \u05d4\u05e8\u05e9\u05de\u05d9 \u05e9\u05dc\u05d4\u05dc\u05df \u05e1\u05de\u05d5\u05da \u05dc\u05e0\u05e1\u05d9\u05e2\u05d4.',
    yi:'\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05e2\u05e0\u05d3\u05e2\u05e8\u05df \u05d6\u05d9\u05da \u05d0\u05d5\u05df \u05d5\u05d5\u05e2\u05e8\u05df \u05d0\u05d9\u05d9\u05e0\u05d2\u05e2\u05e4\u05d9\u05e8\u05d8 \u05d3\u05d5\u05e8\u05da \u05d3\u05e2\u05dd \u05dc\u05d0\u05e0\u05d3 \u05d5\u05d5\u05d0\u05d5\u05d4\u05d9\u05df \u05d0\u05d9\u05e8 \u05e4\u05d0\u05e8\u05d8, \u05e0\u05d9\u05e9\u05d8 \u05d3\u05d5\u05e8\u05da CJHQ. \u05e4\u05d0\u05e8\u05d6\u05d9\u05db\u05e2\u05e8\u05d8 \u05d3\u05d9 \u05d9\u05e2\u05e6\u05d8\u05d9\u05d2\u05e2 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05d1\u05d9\u05d9\u05dd \u05d0\u05e4\u05d9\u05e6\u05d9\u05e2\u05dc\u05df \u05de\u05e7\u05d5\u05e8 \u05d3\u05d0 \u05d0\u05d5\u05e0\u05d8\u05df, \u05e0\u05d0\u05e0\u05d8 \u05e4\u05d0\u05e8 \u05d3\u05e2\u05e8 \u05e8\u05d9\u05d9\u05d6\u05e2.'
  }, L);

  // Hebrew and Yiddish: the country content itself exists in English and French
  // only. Rather than paste English at someone who asked in Yiddish, answer in
  // their language, name the country, and hand them the official source. The
  // gap is recorded so it can be filled rather than quietly persisting.
  if(L === 'he' || L === 'yi'){
    if(typeof __askMissingYi !== 'undefined' && L === 'yi'){
      __askMissingYi.add('SPECIAL_INFO_COUNTRIES body text (' + rec.id + ')');
    }
    r.answer = lead + '\n' + checkNote;
  } else {
    const bullets = before.length ? '\n- ' + before.join('\n- ') : '';
    r.answer = lead + '\n' + (intro || '') + bullets
             + (warning ? '\n\n' + warning : '')
             + '\n\n' + checkNote
             + (rec.lastVerified ? ' (CJHQ last verified: ' + rec.lastVerified + ')' : '');
  }

  r.actions = links.slice(0,3).map(l => ({
    label: (isFr && l.label_fr) ? l.label_fr : (l.label_en || l.label_fr || 'Official source'),
    url: l.url, kind:'link'
  }));
  r.sources = links.slice(0,3).map(l => ({
    name: (isFr && l.label_fr) ? l.label_fr : (l.label_en || 'Official source'),
    url: l.url, type:'Government', authoritative:true, timeSensitive:true,
    lastUpdated: rec.lastVerified || ''
  }));
  return r;
}

function askCommunityDirectory(q){
  const isDirectory = /mikvah|mikveh|mikv\u00e9|\u05de\u05e7\u05d5\u05d5\u05d4|\u05de\u05d9\u05e7\u05d5\u05d5\u05d4|minyan|minyen|\u05de\u05e0\u05d9\u05d9\u05df|shul|schul|synagogue|\u05e9\u05d5\u05dc|\u05d1\u05d9\u05ea \u05db\u05e0\u05e1\u05ea|daven|davening|davenen|pray|prier|\u05d3\u05d0\u05d5\u05d5\u05e0\u05e2\u05df|\u05dc\u05d4\u05ea\u05e4\u05dc\u05dc|kosher|casher|kashrut|cacher|cach\u00e8re|cach\u00e8res|\u05db\u05e9\u05e8/i.test(q);
  if(!isDirectory) return null;
  const r = askAnswerShape();
  const L = askDetectLanguage(q); r.lang = L;
  r.handler = 'Community Directory';

  // Answer from the registry when CJHQ has verified entries. The registry ships
  // EMPTY on purpose: no shul, mikvah or kosher listing is invented here, and
  // an unverified entry is worse than no entry for this kind of question.
  const type = /mikvah|mikveh|mikv\u00e9|\u05de\u05e7\u05d5\u05d5\u05d4/i.test(q) ? 'mikvah'
             : /kosher|casher|kashrut|cacher|cach\u00e8re|cach\u00e8res|\u05db\u05e9\u05e8/i.test(q) ? 'kosher'
             : /minyan|minyen|\u05de\u05e0\u05d9\u05d9\u05df/i.test(q) ? 'minyan'
             : 'shul';
  const hits = (askDirectoryEntries || []).filter(e => e && e.active !== false && e.type === type);

  if(hits.length){
    r.handled = true;
    r.answer = askT({
      en:'CJHQ has ' + hits.length + ' verified listing' + (hits.length===1?'':'s') + ' for this. Details and hours can change, so confirm before relying on them.',
      fr:'CJHQ a ' + hits.length + ' inscription' + (hits.length===1?'':'s') + ' v\u00e9rifi\u00e9e' + (hits.length===1?'':'s') + '. Les d\u00e9tails et les heures peuvent changer; confirmez avant de vous y fier.',
      he:'\u05dc-CJHQ \u05d9\u05e9 ' + hits.length + ' \u05e8\u05e9\u05d5\u05de\u05d5\u05ea \u05de\u05d0\u05d5\u05de\u05ea\u05d5\u05ea. \u05d4\u05e4\u05e8\u05d8\u05d9\u05dd \u05d5\u05d4\u05e9\u05e2\u05d5\u05ea \u05e2\u05e9\u05d5\u05d9\u05d9\u05dd \u05dc\u05d4\u05e9\u05ea\u05e0\u05d5\u05ea; \u05d9\u05e9 \u05dc\u05d0\u05de\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e1\u05ea\u05de\u05db\u05d5\u05ea.',
      yi:'CJHQ \u05d4\u05d0\u05d8 ' + hits.length + ' \u05d1\u05d0\u05e9\u05d8\u05e2\u05d8\u05d9\u05d2\u05d8\u05e2 \u05d0\u05d9\u05d9\u05e0\u05d8\u05e8\u05d0\u05d2\u05df \u05d3\u05e2\u05e8\u05d5\u05d9\u05e3. \u05e4\u05e8\u05d8\u05d9\u05dd \u05d0\u05d5\u05df \u05e9\u05e2\u05d4\u05df \u05e7\u05e2\u05e0\u05e2\u05df \u05d6\u05d9\u05da \u05e2\u05e0\u05d3\u05e2\u05e8\u05df, \u05e4\u05d0\u05e8\u05d6\u05d9\u05db\u05e2\u05e8\u05d8 \u05d6\u05d9\u05da \u05e4\u05d0\u05e8 \u05d0\u05d9\u05e8 \u05e4\u05d0\u05e8\u05dc\u05d0\u05d6\u05d8 \u05d6\u05d9\u05da \u05d3\u05e2\u05e8\u05d5\u05d9\u05e3.'
    }, L);
    r.actions = hits.slice(0,4).map(e => ({ label:e.name, url:e.url || '/resources', kind:e.url ? 'link' : 'internal' }));
    r.sources = hits.slice(0,4).map(e => ({
      name:e.name, url:e.url || '', type:'Community',
      authoritative:!!e.verified, timeSensitive:true,
      lastUpdated:e.lastUpdated || ''
    }));
    return r;
  }

  // CJHQ has no verified listing. Rather than stop at "we don't have this",
  // hand the person to the community directory that does - FindMTL - by
  // category. Nothing from FindMTL is reproduced here.
  const fmKey = (type === 'kosher') ? 'food' : 'shuls';
  r.handled = false;
  r.actions = [askFindMtlAction(fmKey, L),
               { label: askT({en:'CJHQ Resource Centre', fr:'Centre de ressources CJHQ', he:'\u05de\u05e8\u05db\u05d6 \u05d4\u05de\u05e9\u05d0\u05d1\u05d9\u05dd', yi:'CJHQ \u05e8\u05e2\u05e1\u05d5\u05e8\u05e1 \u05e6\u05e2\u05e0\u05d8\u05e2\u05e8'}, L), url:'/resources', kind:'internal' }];
  r.sources = [askFindMtlSource(fmKey)];
  r.answer = askT({
    en:'CJHQ does not maintain a verified directory of shuls, mikvaot, minyanim or kosher food, so I will not list any from memory. FindMTL is the community directory for this - check its '
       + (fmKey === 'food' ? 'kosher food' : 'shul and minyan') + ' listings. Details and hours change, so confirm before relying on them.',
    fr:'Le CJHQ ne tient pas de r\u00e9pertoire v\u00e9rifi\u00e9 des synagogues, mikv\u00e9s, minyanim ou commerces cachers; je n\u2019en citerai donc aucun de m\u00e9moire. FindMTL est le r\u00e9pertoire communautaire pour cela \u2014 consultez ses inscriptions '
       + (fmKey === 'food' ? 'd\u2019alimentation cach\u00e8re' : 'de synagogues et minyanim') + '. Les d\u00e9tails et les heures changent; confirmez avant de vous y fier.',
    he:'\u05dc-CJHQ \u05d0\u05d9\u05df \u05de\u05d0\u05d2\u05e8 \u05de\u05d0\u05d5\u05de\u05ea \u05e9\u05dc \u05d1\u05ea\u05d9 \u05db\u05e0\u05e1\u05ea, \u05de\u05e7\u05d5\u05d5\u05d0\u05d5\u05ea, \u05de\u05e0\u05d9\u05e0\u05d9\u05dd \u05d0\u05d5 \u05de\u05d6\u05d5\u05df \u05db\u05e9\u05e8, \u05dc\u05db\u05df \u05dc\u05d0 \u05d0\u05e6\u05d9\u05d9\u05df \u05e8\u05e9\u05d5\u05de\u05d5\u05ea \u05de\u05d4\u05d6\u05d9\u05db\u05e8\u05d5\u05df. FindMTL \u05d4\u05d5\u05d0 \u05de\u05d3\u05e8\u05d9\u05da \u05d4\u05e7\u05d4\u05d9\u05dc\u05d4 \u05dc\u05e2\u05e0\u05d9\u05d9\u05df \u05d6\u05d4. \u05d4\u05e4\u05e8\u05d8\u05d9\u05dd \u05d5\u05d4\u05e9\u05e2\u05d5\u05ea \u05de\u05e9\u05ea\u05e0\u05d9\u05dd; \u05d9\u05e9 \u05dc\u05d0\u05de\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e1\u05ea\u05de\u05db\u05d5\u05ea.',
    yi:'CJHQ \u05d4\u05d0\u05dc\u05d8 \u05e0\u05d0\u05da \u05e0\u05d9\u05e9\u05d8 \u05e7\u05d9\u05d9\u05df \u05d1\u05d0\u05e9\u05d8\u05e2\u05d8\u05d9\u05d2\u05d8\u05e2 \u05e8\u05e9\u05d9\u05de\u05d4 \u05e4\u05d5\u05df \u05e9\u05d5\u05dc\u05df, \u05de\u05e7\u05d5\u05d5\u05d0\u05d5\u05ea, \u05de\u05e0\u05d9\u05e0\u05d9\u05dd \u05d0\u05d3\u05e2\u05e8 \u05db\u05e9\u05e8 \u05e2\u05e1\u05df, \u05d3\u05e2\u05e8\u05d9\u05d1\u05e2\u05e8 \u05e7\u05e2\u05df \u05d0\u05d9\u05da \u05d3\u05d0\u05e1 \u05e0\u05d9\u05e9\u05d8 \u05e2\u05e0\u05d8\u05e4\u05e2\u05e8\u05df \u05d0\u05d5\u05d9\u05e3 \u05d0 \u05e4\u05d0\u05e8\u05dc\u05d0\u05d6\u05dc\u05e2\u05db\u05df \u05d0\u05d5\u05e4\u05df. \u05d0 \u05e7\u05d4\u05d9\u05dc\u05d4 \u05d3\u05d9\u05e8\u05e2\u05e7\u05d8\u05d0\u05e8\u05d9\u05e2 \u05d0\u05d9\u05d6 \u05d3\u05e2\u05e8 \u05e8\u05d9\u05db\u05d8\u05d9\u05d2\u05e2\u05e8 \u05de\u05e7\u05d5\u05e8 \u05d3\u05e2\u05e8\u05e4\u05d0\u05e8, \u05d0\u05d5\u05df \u05d3\u05d0\u05e1 \u05d0\u05e0\u05e6\u05d5\u05e9\u05dc\u05d9\u05e1\u05df \u05e7\u05d5\u05de\u05d8 \u05e0\u05d0\u05da.'
  }, L);
  return r;
}

/* ---------- CJHQ resource answers ----------
   The resource records already contain the whole popup: what_*, the numbered
   steps_list_*, the need_list_* of required documents, tips_list_*, a
   question and answer pair, and official_links[0] - the actual action link.
   This handler used to read four of those fields and answer "CJHQ has a
   resource for that: X", attaching up to three links. The information needed
   to answer the question was sitting unused in the same record.

   Two rules govern what comes back:

   SPECIFICITY, not a bare score ratio. A hit is specific when the question
   actually names it - titleHits > 0, meaning a word from the resource title
   appears in the question - AND it is clearly ahead of the runner-up. "Apply
   for NEXUS" wins on "how do I apply for NEXUS" because NEXUS is in its title;
   RAMQ scores on "apply" alone and is not named, so it loses. Where two
   resources are genuinely close and neither is named, the honest response is
   to ask which one, not to answer confidently about the wrong one.

   QUESTION SHAPE. The record is structured, so the answer can match what was
   asked: a process question gets the steps, a "what do I need" question gets
   the document list, a "what is" question gets the description. Sending every
   field for every question is the same failure as sending every link.

   ONE source of truth: this reads the same array the website popup renders, so
   editing a resource improves both. Nothing is duplicated here.              */

/* Kept deliberately compact. ask-core.mjs is shared with the WhatsApp bridge,
   where a wall of text is worse than useless - so steps are capped, tips only
   appear when asked for, and the link goes last. */
const ASK_RES_MAX_STEPS = 6;

const ASK_RES_INTENT = {
  steps: /\bhow (?:do|can|would) i\b|\bprocess\b|\bapply\b|\bapplication\b|\bsteps?\b|\brenew\b|\bregister\b|comment (?:faire|puis-je)|d[ée]marche|proc[ée]dure|demande|\u05d0\u05d9\u05da \u05de\u05d2\u05d9\u05e9|\u05ea\u05d4\u05dc\u05d9\u05da|\u05d5\u05d5\u05d9 \u05d0\u05d6\u05d5\u05d9/i,
  needs: /what (?:do i |will i )?need|\brequired\b|\brequirements?\b|\bdocuments?\b|\bbring\b|\bqualif/i,
  what:  /^\s*(?:what(?:'s| is)|c'est quoi|qu'est-ce que|\u05de\u05d4 \u05d6\u05d4|\u05d5\u05d5\u05d0\u05e1 \u05d0\u05d9\u05d6)\b/i,
  right: /is this the right|am i eligible|do i qualify|est-ce la bonne/i
};

function askResourceIntent(q){
  const s = String(q || '');
  if(ASK_RES_INTENT.right.test(s)) return 'right';
  if(ASK_RES_INTENT.needs.test(s)) return 'needs';
  if(ASK_RES_INTENT.steps.test(s)) return 'steps';
  if(ASK_RES_INTENT.what.test(s))  return 'what';
  return 'general';
}

/* A hit is specific when the question named it and it is clearly ahead. */
function askResourceIsSpecific(hits){
  if(!hits.length) return false;
  const top = hits[0];
  if(!(top.titleHits > 0)) return false;
  if(hits.length === 1) return true;
  // More of the question's words in this title than in the runner-up's is the
  // clearest signal there is: "how do I apply for a passport" hits two words of
  // "Adult Passport Application" and one of "Passport Renewal", so the
  // application wins and no clarification is needed. Falling back to the score
  // ratio covers the case where titles tie but relevance does not.
  if(top.titleHits > hits[1].titleHits) return true;
  return top.score >= hits[1].score * 1.5 || hits[1].titleHits === 0;
}

function askCjhqResources(q){
  const hits = askMatchResources(q, 3);
  if(!hits.length) return null;
  const r = askAnswerShape();
  const L = askDetectLanguage(q); r.lang = L;
  r.handler = 'CJHQ Resources';
  const isFr = (L === 'fr');
  const pick = (en, fr) => (isFr && fr) ? fr : en;
  const top = hits[0].item;
  const topName = pick(top.en, top.fr);

  // Genuinely ambiguous: two close hits, neither named by the question. Ask
  // rather than answer confidently about whichever scored marginally higher.
  if(!askResourceIsSpecific(hits) && hits.length > 1 && hits[1].score >= hits[0].score * 0.85){
    r.handled = false;
    const names = hits.slice(0, 3).map(h => pick(h.item.en, h.item.fr));
    r.answer = askT({
      en:'That could be a few different CJHQ resources: ' + names.join(', ') + '. Which one do you mean?',
      fr:'Cela pourrait correspondre \u00e0 plusieurs ressources du CJHQ\u00a0: ' + names.join(', ') + '. Laquelle vous int\u00e9resse\u00a0?',
      he:'\u05d6\u05d4 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05ea\u05d0\u05d9\u05dd \u05dc\u05db\u05de\u05d4 \u05de\u05e9\u05d0\u05d1\u05d9\u05dd \u05e9\u05dc CJHQ: ' + names.join(', ') + '. \u05dc\u05d0\u05d9\u05d6\u05d4 \u05db\u05d5\u05d5\u05e0\u05ea\u05dd?',
      yi:'\u05d3\u05d0\u05e1 \u05e7\u05e2\u05df \u05d6\u05d9\u05d9\u05df \u05e2\u05d8\u05dc\u05e2\u05db\u05e2 CJHQ \u05e8\u05e2\u05e1\u05d5\u05e8\u05e1\u05df: ' + names.join(', ') + '. \u05d5\u05d5\u05e2\u05dc\u05db\u05e2\u05e8 \u05de\u05d9\u05d9\u05e0\u05d8 \u05d0\u05d9\u05e8?'
    }, L);
    r.actions = hits.slice(0, 3).map(h => ({
      label: pick(h.item.en, h.item.fr),
      url: h.item.internalPage ? ('/' + h.item.internalPage) : ('/resources/' + h.item.slug),
      kind:'internal'
    }));
    return r;
  }

  r.handled = true;
  const intent = askResourceIntent(q);

  // Hebrew and Yiddish: the record bodies exist in English and French only.
  // Rather than paste English at someone who asked in Yiddish, name the
  // resource in their language and hand over the link. The gap is recorded so
  // it can be filled rather than quietly persisting.
  if(L === 'he' || L === 'yi'){
    if(L === 'yi' && typeof __askMissingYi !== 'undefined'){
      __askMissingYi.add('resource body text (' + top.slug + ')');
    }
    r.answer = askT({
      en:'', fr:'',
      he:'\u05dc-CJHQ \u05d9\u05e9 \u05de\u05e9\u05d0\u05d1 \u05dc\u05db\u05da: ' + topName + '. \u05d4\u05e4\u05e8\u05d8\u05d9\u05dd \u05d4\u05de\u05dc\u05d0\u05d9\u05dd \u05d5\u05d4\u05e7\u05d9\u05e9\u05d5\u05e8 \u05d4\u05e8\u05e9\u05de\u05d9 \u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05dc\u05d4\u05dc\u05df.',
      yi:'CJHQ \u05d4\u05d0\u05d8 \u05d0 \u05e8\u05e2\u05e1\u05d5\u05e8\u05e1 \u05d3\u05e2\u05e8\u05e4\u05d0\u05e8: ' + topName + '. \u05d3\u05d9 \u05e4\u05d5\u05dc\u05e2 \u05e4\u05e8\u05d8\u05d9\u05dd \u05d0\u05d5\u05df \u05d3\u05e2\u05e8 \u05d0\u05e4\u05d9\u05e6\u05d9\u05e2\u05dc\u05e2\u05e8 \u05dc\u05d9\u05e0\u05e7 \u05d6\u05e2\u05e0\u05e2\u05df \u05d3\u05d0 \u05d0\u05d5\u05e0\u05d8\u05df.'
    }, L);
  } else {
    const parts = [];
    const what = pick(top.what_en, top.what_fr) || pick(top.desc_en, top.desc_fr);
    if(what) parts.push(what);

    if(intent === 'right' && pick(top.answer_en, top.answer_fr)){
      parts.push(pick(top.answer_en, top.answer_fr));
    }

    const needList = isFr ? top.need_list_fr : top.need_list_en;
    if((intent === 'needs' || intent === 'general') && Array.isArray(needList) && needList.length){
      const head = pick(top.need_heading_en, top.need_heading_fr);
      parts.push((head ? head + '\n' : '') + needList.map(x => '- ' + x).join('\n'));
    }

    const stepList = isFr ? top.steps_list_fr : top.steps_list_en;
    if((intent === 'steps' || intent === 'general') && Array.isArray(stepList) && stepList.length){
      const head = pick(top.steps_heading_en, top.steps_heading_fr);
      const shown = stepList.slice(0, ASK_RES_MAX_STEPS);
      parts.push((head ? head + '\n' : '')
        + shown.map((x, n) => (n + 1) + '. ' + x).join('\n')
        + (stepList.length > shown.length ? '\n\u2026' : ''));
    }

    // Tips are caveats, not process. They earn their space only when the
    // person is about to act, which is the steps and needs case.
    const tipList = isFr ? top.tips_list_fr : top.tips_list_en;
    if((intent === 'steps' || intent === 'needs') && Array.isArray(tipList) && tipList.length){
      const head = pick(top.tips_heading_en, top.tips_heading_fr);
      parts.push((head ? head + '\n' : '') + tipList.map(x => '- ' + x).join('\n'));
    }

    r.answer = parts.join('\n\n');
  }

  // One action link, from the resource itself, plus its CJHQ page. No siblings.
  const official = Array.isArray(top.official_links) ? top.official_links[0] : null;
  r.actions = [];
  if(official && official.url){
    r.actions.push({ label: pick(official.label_en, official.label_fr) || topName,
                     url: official.url, kind:'link' });
  }
  r.actions.push({ label: topName,
                   url: top.internalPage ? ('/' + top.internalPage) : ('/resources/' + top.slug),
                   kind:'internal' });
  r.sources = [{ name: top.en, url:'https://cjhq.org/resources/' + top.slug,
                 type:'CJHQ', authoritative:true, timeSensitive:false,
                 category: hits[0].category, score: hits[0].score }];
  return r;
}

/* ---------- provider-independent entry point ----------
   The UI only ever calls this. Swapping in a real AI gateway means implementing
   ASK_BACKEND.ask() - no other part of the app changes. */
/* Build the context Gemini is allowed to use. Only verified material from the
   deterministic layer goes in - never the raw question, never model memory. */
function askBuildContext(res){
  const parts = [];
  if(res.answer) parts.push('Verified CJHQ answer: ' + res.answer);
  if(res.location) parts.push('Location: ' + res.location);
  if(res.timeSensitive) parts.push('NOTE: this information is time-sensitive. Do not state a specific time, date or status.');
  if(res.halachic) parts.push('NOTE: the user is asking for a halachic ruling. Do NOT give one, do not '
    + 'reason towards one, and do not present the practical information as if it settled the question. '
    + 'Keep the referral to their rov. Do not name any rabbi, organisation or phone number.');
  (res.sources || []).forEach(src=>{
    parts.push('Source: ' + src.name + (src.url ? ' <' + src.url + '>' : '')
      + (src.authoritative ? ' [authoritative]' : '')
      + (src.timeSensitive ? ' [time-sensitive]' : ''));
  });
  (res.actions || []).forEach(a=>{
    parts.push('Link offered to the user: ' + a.label + ' <' + a.url + '>');
  });
  return parts.join('\n');
}

/* askRun is the shared engine. It takes the AI layer as an argument rather
   than reaching for ASK_BACKEND / firebaseReady / appCheckReady in file scope,
   which is what previously tied the whole orchestrator to a browser.

   aiAdapter is optional and duck-typed: { ready(): boolean,
   ask(question, context): Promise<string> }. Omit it - as the WhatsApp bridge
   does - and the deterministic path runs alone, which is the same path the
   site already falls back to whenever Gemini is unavailable.

   The handler order, the halachic guard's primacy and every answer string are
   untouched by this change. */
/* ---------- phrasing verification ----------
   The old acceptance test was `phrased.length > 10`. This replaces it with
   checks for problems that can actually be DETECTED, and nothing else.

   Deliberately NOT grounds for rejection: being short, being worded
   differently from the deterministic answer, or reordering the content. A
   verifier that rejects good phrasing makes the assistant worse, because the
   fallback is the terser deterministic text.

   Every check below is mechanical. Nothing here asks a model to judge another
   model - that would just add a third opinion with no more authority than the
   first two. Returns null when the phrasing is acceptable, otherwise a short
   machine-readable reason used to build the review prompt.                   */
const ASK_PHRASE_REFUSAL = /\b(?:i (?:cannot|can't|am unable to|don't have (?:access|enough))|as an ai|i'?m (?:just )?an ai|unable to (?:help|assist|provide))\b/i;
const ASK_PHRASE_RULING  = /\b(?:it is (?:permitted|forbidden|allowed|prohibited)|you may carry|is mutar|is assur|the halacha is|halachically (?:permitted|forbidden))\b/i;
const ASK_PHRASE_CLOCK   = /\b\d{1,2}:\d{2}\b|\b\d{1,2}\s?(?:am|pm)\b/i;

function askPhraseTokens(v){
  return String(v || '').toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 3);
}

function askVerifyPhrasing(phrased, question, res, context){
  const p = String(phrased || '').trim();
  if(p.length < 10) return 'empty';

  // 1. Invented links. Any URL in the answer must already appear in the
  //    verified material or in the actions the deterministic layer chose.
  const allowed = (context || '') + ' '
    + (res.actions || []).map(a => a.url).join(' ') + ' '
    + (res.sources || []).map(x => x.url || '').join(' ');
  const urls = p.match(/https?:\/\/[^\s<>")']+/g) || [];
  for(const u of urls){
    const bare = u.replace(/[.,;:)]+$/, '');
    if(allowed.indexOf(bare) < 0) return 'invented-link';
  }

  // 2. Invented phone numbers. The highest-consequence hallucination this
  //    assistant could produce, so it is checked separately from links.
  const nums = p.match(/\b(?:\+?1[-. ]?)?\(?\d{3}\)?[-. ]\d{3}[-. ]\d{4}\b/g) || [];
  for(const n of nums){ if(allowed.indexOf(n) < 0) return 'invented-number'; }

  // 3. Unnecessary refusal. CJHQ has a verified answer in hand; declining to
  //    give it is a failure of the phrasing pass, not a safety behaviour.
  if(ASK_PHRASE_REFUSAL.test(p)) return 'refused';

  // A language check used to sit here and has been REMOVED, deliberately.
  // askDetectLanguage() classifies QUESTIONS: French needs an interrogative
  // marker or two weak hits. Answers are declarative, so a correct French
  // answer to a French question classified as English and was rejected -
  // costing French users a second call and usually the terser deterministic
  // text. It is not being tuned or replaced with a script check: the review
  // prompt already says "Answer in the same language as the question", and a
  // wrong-language reply is a quality problem, not a safety one, unlike an
  // invented phone number. Do not reintroduce it without an answer-language
  // classifier that has been validated on real answers.

  // 4. Time-sensitive contradiction. The deterministic layer deliberately
  //    refuses to state a time or status; the model must not add one back.
  if(res.timeSensitive && ASK_PHRASE_CLOCK.test(p)) return 'stated-time';

  // 5. Halachic. The referral must survive and no ruling may appear.
  if(res.halachic){
    if(ASK_PHRASE_RULING.test(p)) return 'issued-ruling';
    if(!/\brov\b|\brav\b|\u05d4\u05e8\u05d1|\u05e8\u05d1/i.test(p)) return 'dropped-referral';
  }

  // 6. Irrelevance. Shares no substantive word with the verified answer. This
  //    is a blunt test on purpose: it catches an answer about a different
  //    subject without penalising a rewrite that says the same thing.
  const src = new Set(askPhraseTokens(res.answer).concat(askPhraseTokens(question)));
  if(src.size){
    const overlap = askPhraseTokens(p).filter(w => src.has(w));
    if(!overlap.length) return 'irrelevant';
  }
  return null;
}

/* The review pass. Same model and settings - only the instruction differs.
   It is given the question, the verified material and the first attempt, and
   told what was wrong with it. */
function askBuildReviewContext(context, first, reason){
  return context
    + '\n\nA previous draft answer was rejected. Reason: ' + reason + '.'
    + '\nPrevious draft: ' + String(first || '').slice(0, 1200)
    + '\nRewrite it. Use ONLY the verified CJHQ information above. Do not add any'
    + ' URL, phone number, time, date or fact that does not appear there. Do not'
    + ' refuse - the verified answer is present. Answer in the same language as'
    + ' the question. Correct the omissions, unsupported claims and contradictions'
    + ' in the previous draft.';
}

async function askRun(question, opts, aiAdapter){
  const q = String(question || '').trim();
  if(!q) return null;
  const useAI = !(opts && opts.useAI === false);

  // Structured and CJHQ answers first: they are verifiable and need no AI.
  // Order matters: the directory guard runs before the resource matcher so a
  // community question cannot be answered with an unrelated CJHQ resource.
  // askHalachic runs FIRST. Without that, an explicitly halachic question is
  // answered by whichever practical handler matches a keyword in it, and the
  // answer reads as a ruling.
  const handlers = [askHalachic].concat(askPracticalHandlers());
  let res = null;
  for(const h of handlers){
    const out = h(q, opts);
    if(out){ res = out; break; }
  }

  if(!res){
    // Nothing verified to ground on. Gemini is NOT called here - a model asked
    // to answer with no context is exactly how invented facts appear.
    const r = askAnswerShape();
    const L = askDetectLanguage(q); r.lang = L;
    r.handled = false; r.handler = 'none';
    r.answer = askT({
      en:'I could not match that to a CJHQ resource or a structured source, so I am not going to guess. Try the Resource Centre, or rephrase using a keyword such as passport, NEXUS, RAMQ, eruv, zmanim or Hatzolah.',
      fr:'Je n\u2019ai pas pu rattacher cela \u00e0 une ressource CJHQ ni \u00e0 une source structur\u00e9e; je ne vais donc pas deviner. Essayez le Centre de ressources, ou reformulez avec un mot-cl\u00e9 comme passeport, NEXUS, RAMQ, \u00e9rouv, zmanim ou Hatzolah.',
      he:'\u05dc\u05d0 \u05d4\u05e6\u05dc\u05d7\u05ea\u05d9 \u05dc\u05d4\u05ea\u05d0\u05d9\u05dd \u05d0\u05ea \u05d6\u05d4 \u05dc\u05de\u05e9\u05d0\u05d1 \u05e9\u05dc CJHQ \u05d0\u05d5 \u05dc\u05de\u05e7\u05d5\u05e8 \u05de\u05d5\u05d1\u05e0\u05d4, \u05dc\u05db\u05df \u05dc\u05d0 \u05d0\u05e0\u05d7\u05e9. \u05e0\u05e1\u05d5 \u05d0\u05ea \u05de\u05e8\u05db\u05d6 \u05d4\u05de\u05e9\u05d0\u05d1\u05d9\u05dd.',
      yi:'\u05d0\u05d9\u05da \u05d4\u05d0\u05d1 \u05d3\u05d0\u05e1 \u05e0\u05d9\u05e9\u05d8 \u05d2\u05e2\u05e7\u05e2\u05e0\u05d8 \u05e6\u05d5\u05e4\u05d0\u05e1\u05df \u05e6\u05d5 \u05e7\u05d9\u05d9\u05df CJHQ \u05e8\u05e2\u05e1\u05d5\u05e8\u05e1 \u05d0\u05d3\u05e2\u05e8 \u05e1\u05d8\u05e8\u05d5\u05e7\u05d8\u05d5\u05e8\u05d9\u05e8\u05d8\u05df \u05de\u05e7\u05d5\u05e8, \u05d3\u05e2\u05e8\u05d9\u05d1\u05e2\u05e8 \u05d5\u05d5\u05e2\u05dc \u05d0\u05d9\u05da \u05e0\u05d9\u05e9\u05d8 \u05d8\u05e8\u05e2\u05e4\u05df. \u05e4\u05e8\u05d5\u05d1\u05d9\u05e8\u05d8 \u05d3\u05e2\u05dd \u05e8\u05e2\u05e1\u05d5\u05e8\u05e1 \u05e6\u05e2\u05e0\u05d8\u05e2\u05e8, \u05d0\u05d3\u05e2\u05e8 \u05e9\u05e8\u05d9\u05d9\u05d1\u05d8 \u05e2\u05e1 \u05d0\u05d9\u05d1\u05e2\u05e8 \u05de\u05d9\u05d8 \u05d0 \u05d5\u05d5\u05d0\u05e8\u05d8 \u05d5\u05d5\u05d9 \u05e4\u05d0\u05e1\u05e4\u05d0\u05e8\u05d8, NEXUS, RAMQ, \u05e2\u05d9\u05e8\u05d5\u05d1, \u05d6\u05de\u05e0\u05d9\u05dd \u05d0\u05d3\u05e2\u05e8 \u05d4\u05e6\u05dc\u05d4.'
    }, L);
    r.actions = [{ label: askT({en:'CJHQ Resource Centre', fr:'Centre de ressources CJHQ', he:'\u05de\u05e8\u05db\u05d6 \u05d4\u05de\u05e9\u05d0\u05d1\u05d9\u05dd', yi:'CJHQ \u05e8\u05e2\u05e1\u05d5\u05e8\u05e1 \u05e6\u05e2\u05e0\u05d8\u05e2\u05e8'}, L), url:'/resources', kind:'internal' }];
    return r;
  }

  // A handler matched. Its answer is already correct and safe, so AI is a
  // presentation layer on top: if Gemini is unavailable, slow, throttled or
  // returns nothing usable, the deterministic answer is what the user sees.
  res.aiUsed = false;
  const aiReady = !!(aiAdapter && typeof aiAdapter.ask === 'function'
                     && (typeof aiAdapter.ready !== 'function' || aiAdapter.ready()));
  if(useAI && aiReady){
    const context = askBuildContext(res);
    if(context){
      try{
        const t0 = Date.now();
        // HARD CEILING: two calls. Attempt 2 runs only when attempt 1 has a
        // concrete detectable problem, so a well-behaved answer costs one call
        // exactly as before. On the free tier a second call also means a second
        // throttle wait, so it is not spent speculatively.
        let phrased = await aiAdapter.ask(q, context);
        res.aiAttempts = 1;
        let reason = askVerifyPhrasing(phrased, q, res, context);

        if(reason){
          res.aiRejected = reason;
          res.aiRejectedDraft = String(phrased || '').slice(0, 400);
          const phrased2 = await aiAdapter.ask(q, askBuildReviewContext(context, phrased, reason));
          res.aiAttempts = 2;
          const reason2 = askVerifyPhrasing(phrased2, q, res, context);
          if(reason2){
            // Both attempts failed verification. The verified CJHQ answer
            // stands - it is correct, just plainer. Never noAnswer: CJHQ has
            // the information, only the phrasing failed.
            res.aiRejected2 = reason2;
            phrased = null;
          }else{
            phrased = phrased2;
          }
        }
        res.aiLatencyMs = Date.now() - t0;

        if(phrased){
          res.deterministicAnswer = res.answer;  // kept for admin comparison
          res.answer = phrased;
          res.aiUsed = true;
          res.aiModel = (aiAdapter && aiAdapter.model) || '';
        }
      }catch(err){
        // Never surface provider detail to a user. Quota, rate limits and
        // billing errors all look the same from outside: the assistant simply
        // answers from CJHQ's own information.
        res.aiError = String((err && err.message) || err).slice(0, 120);
        console.warn('[CJHQ] Ask CJHQ AI unavailable, using verified answer:', res.aiError);
      }
    }
  }
  return res;
}

/* Public entry point for a non-browser caller (the WhatsApp bridge). Returns
   only the fields that belong in a user-facing answer: the diagnostic fields
   askRun also sets - deterministicAnswer, aiError, aiModel, aiLatencyMs - are
   admin material and are deliberately not included. */
async function askAnswer(input){
  const opts = (input && typeof input === 'object') ? input : { text: String(input || '') };
  const text = String(opts.text || '');
  // Optional conversation context, supplied per call by the caller and NEVER
  // stored here. The core stays stateless, which is what guarantees one
  // WhatsApp chat cannot leak into another: there is nothing to leak from.
  // The bridge owns chat id, the recent-message window, expiry and isolation.
  const res  = await askRun(text, {
    useAI: opts.useAI === true,
    context: Array.isArray(opts.context) ? opts.context.slice(-6) : null,
    orgContacts: (opts.orgContacts && typeof opts.orgContacts === 'object') ? opts.orgContacts : null
  }, opts.aiAdapter);
  if(!res){
    return { answer:'', sources:[], actions:[], timeSensitive:false,
             handled:false, handler:'', lang:'en', location:'', halachic:false };
  }
  return {
    answer:        res.answer || '',
    sources:       (res.sources || []).map(s => ({ name: s.name, url: s.url || '' })),
    actions:       (res.actions || []).map(a => ({ label: a.label, url: a.url, kind: a.kind || 'link' })),
    timeSensitive: !!res.timeSensitive,
    handled:       !!res.handled,
    handler:       res.handler || '',
    lang:          res.lang || 'en',
    location:      res.location || '',
    halachic:      !!res.halachic
  };
}
